--[[
	Midnight Helper — 2.0 translation fills for de/fr/es/pt (post-2025 features).

	Load order: AFTER the main pack files (deDE/frFR/esES/ptBR.lua build their
	tables), so ns._mhLocales.<pack> already exists. Uses a FILL-ONLY merge:
	a key is only set when the pack doesn't already have it, so existing
	translations are never overwritten — safe to apply the same set to all four.

	Intentionally English (NOT here): CHANGELOG_* (older entries stay English),
	rune/boss/zone item names, and game terms (Mythic+, PvP, Raid) — these keep
	the enUS fallback on purpose.
]]

local _, ns = ...

local function fill(code, patch)
	local t = ns._mhLocales and ns._mhLocales[code]
	if type(t) ~= "table" or type(patch) ~= "table" then
		return
	end
	for k, v in pairs(patch) do
		if t[k] == nil then
			t[k] = v
		end
	end
end

